package lk.ac.sliit.ridelink.driver.presentation.controller;
import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import lk.ac.sliit.ridelink.driver.application.dto.response.*; import lk.ac.sliit.ridelink.driver.application.port.in.DriverVehicleUseCase; import lk.ac.sliit.ridelink.driver.domain.enums.VehicleType; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/internal/drivers") @Tag(name="Internal driver contract") @SecurityRequirement(name="bearerAuth") public class InternalDriverController {private final DriverVehicleUseCase service;public InternalDriverController(DriverVehicleUseCase s){service=s;}@GetMapping("/eligible")public List<EligibleDriverResponse> eligible(@RequestParam String serviceArea,@RequestParam VehicleType vehicleType){return service.findEligible(serviceArea,vehicleType);}@PutMapping("/{driverId}/assignments/{rideId}")public DriverProfileResponse assign(@PathVariable UUID driverId,@PathVariable UUID rideId){return service.assign(driverId,rideId);}@DeleteMapping("/{driverId}/assignments/{rideId}")public DriverProfileResponse restore(@PathVariable UUID driverId,@PathVariable UUID rideId){return service.restore(driverId,rideId);}}
